glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = cc_matViewProj * vec4(a_position, 1.0);
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 color;
in vec2 uv0;
layout(std140) uniform Constant {
  vec4 mainColor;
  vec4 params;
  vec4 params2;
};
#define TAU 6.28318530718
#define PI  3.14159265359
float sdCircle(vec2 p, float r){ return length(p) - r; }
float sdStar5(vec2 p, float rad, float rf){
  const vec2 k1 = vec2(0.809016994375, -0.587785252292);
  const vec2 k2 = vec2(-k1.x, k1.y);
  p.x = abs(p.x);
  p -= 2.0 * max(dot(k1, p), 0.0) * k1;
  p -= 2.0 * max(dot(k2, p), 0.0) * k2;
  p.x = abs(p.x); p.y -= rad;
  vec2 ba = rf * vec2(-k1.y, k1.x) - vec2(0, 1);
  float h = clamp(dot(p, ba) / dot(ba, ba), 0.0, rad);
  return length(p - ba * h) * sign(p.y * ba.x - p.x * ba.y);
}
float sdHex(vec2 p, float r){
  const vec3 k = vec3(-0.866025404, 0.5, 0.577350269);
  p = abs(p);
  p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
  p -= vec2(clamp(p.x, -k.z * r, k.z * r), r);
  return length(p) * sign(p.y);
}
vec4 frag () {
  vec2 p = uv0 * 2.0 - 1.0;
  float t = cc_time.x;
  float type = params.x, spin = params.y, lw = params.z, sz = params.w;
  float phase = params2.x, breath = params2.y;
  float a = spin * t * TAU;
  float ca = cos(a), sa = sin(a);
  p = mat2(ca, -sa, sa, ca) * p;
  float d = 1.0;
  if (type < 0.5) {
    float main = sdCircle(p, sz);
    float off = (phase - 0.5) * sz * 2.4;
    float bite = sdCircle(p - vec2(off, 0.0), sz * 0.96);
    d = max(main, -bite);
  } else if (type < 1.5) {
    d = sdStar5(p, sz, 0.382);
  } else if (type < 2.5) {
    float c = sdCircle(p, sz * 0.55);
    float ang = atan(p.y, p.x);
    float spike = abs(fract(ang / (TAU / 8.0)) - 0.5) * 2.0;
    float ray = length(p) - sz * (0.65 + 0.30 * smoothstep(0.85, 1.0, 1.0 - spike));
    d = min(c, ray);
  } else {
    d = sdHex(p, sz);
  }
  float edge = exp(-abs(d) / max(lw, 0.005));
  float inner = exp(d * 6.0) * step(d, 0.0) * 0.18;
  float br = (breath > 0.5) ? (0.7 + 0.3 * sin(t * 1.6)) : 1.0;
  vec3 c = mainColor.rgb;
  vec3 col = c * edge * 0.7 * br + c * inner;
  col *= mainColor.a;
  float al = clamp(max(col.r, max(col.g, col.b)) * 1.3, 0.0, 1.0);
  return vec4(col, al);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

